package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.uiapi.*;
import dev.tacticalcombat.rules.srd.SrdAuthoring;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;

/** Source geometry/style contracts and real constructed controls; no rendered screenshot claim. */
public final class CheckpointEPresentationTests {
    private static int count;
    private static void check(boolean v,String why){if(!v)throw new AssertionError(why);count++;}
    private static List<?> list(CharacterCanvas pane,String key)throws Exception {var f=CharacterCanvas.class.getDeclaredField(key);f.setAccessible(true);return (List<?>)f.get(pane);}
    private static Object field(Object record,String key)throws Exception {var m=record.getClass().getDeclaredMethod(key);m.setAccessible(true);return m.invoke(record);}
    public static void run()throws Exception {
        var snapshot=args("id",UUID.randomUUID(),"name","Test hero","profile","srd_5_1","mode","GUIDED","stage","DRAFT","revision",1,"sheet",SrdAuthoring.template());var sheet=snapshot.getAsJsonObject("sheet");var identity=SheetSections.raw(sheet,"identity");identity.addProperty("species","Elf — High Elf");identity.addProperty("characterClass","Wizard");identity.addProperty("subclass","School of Evocation");identity.addProperty("age","Not set");identity.addProperty("height","Not set");identity.addProperty("alignment","Chaotic Good");snapshot.add("sheet",SheetSections.update(sheet,"identity",identity));
        for(int width:List.of(180,240,320,456,720,900)){var header=SheetHeader.layout(snapshot,width,s->s.length()*6);for(var line:header.lines()){check(line.y()+9<header.height(),"Header reserves bottom padding for each measured line");check(line.x()+line.width()<=width-19,"Header text stays inside horizontal padding");check(line.text().length()*6<=line.width()||line.text().length()==1,"Header wraps rather than overflows");}check(CharacterSheetUi.layout(width,header.height()).equipmentTop()>header.height(),"Abilities/stats begin after measured identity height");}
        var longRecord=snapshot.deepCopy();longRecord.addProperty("name","An extremely long adventurer name with many words and aLongWordWithoutAnySpacesThatMustWrap");var longIdentity=SheetSections.read(longRecord.getAsJsonObject("sheet"),"identity");longIdentity.addProperty("age","One hundred and twenty years old");longIdentity.addProperty("height","Very tall at seven feet and four inches");longRecord.add("sheet",SheetSections.update(longRecord.getAsJsonObject("sheet"),"identity",longIdentity));check(SheetHeader.layout(longRecord,320,s->s.length()*6).height()>SheetHeader.layout(snapshot,320,s->s.length()*6).height(),"Long values increase reserved height rather than collide with abilities");
        var pane=new CharacterCanvas(new UiLayout.Rect(0,0,456,300));CharacterSheetUi.build(pane,snapshot,true,new CharacterSheetUi.Actions(){public boolean healthEditable(){return true;}public boolean trackable(String s){return true;}public void health(String k,int d){}public void track(RpgRecords.Change c){}public void inspect(FeatureReference.Entry e){}public void encounters(){}public boolean campaign(){return false;}},null,null);var controls=list(pane,"controls");var positions=new HashMap<String,UiLayout.Rect>();for(var control:controls){String key=field(control,"key").toString();var widget=(net.minecraft.client.gui.widget.ClickableWidget)field(control,"widget");positions.put(key,new UiLayout.Rect((Integer)field(control,"x"),(Integer)field(control,"y"),widget.getWidth(),widget.getHeight()));}
        for(String key:List.of("hp","temporary_hp")){var minus=positions.get("health:"+key+":-");var plus=positions.get("health:"+key+":+");check(plus.x()-minus.x()==20&&plus.y()==minus.y(),"HP controls are adjacent at the right of each value row");check(minus.width()==18&&plus.width()==18&&!minus.overlaps(plus),"Matching health hitboxes do not overlap");}
        for(boolean filled:List.of(false,true))for(int y=0;y<14;y++)for(int x=0;x<14;x++){boolean pixel=RpgButton.markerPixel(x,y,14,filled);check(pixel==RpgButton.markerPixel(13-x,y,14,filled)&&pixel==RpgButton.markerPixel(x,13-y,14,filled),"Death marker is symmetric about its hitbox center");if(pixel)check(x>=3&&y>=3&&x<11&&y<11,"Marker leaves deliberate centered padding");}
        check(RpgButton.bodyColor(false,true)==RpgButton.bodyColor(false,false)&&RpgButton.bodyColor(false,false)!=RpgButton.bodyColor(true,false),"Unavailable controls have darker body and no hover affordance");check(RpgButton.disabledColor()!=RpgTheme.TEXT&&RpgButton.disabledColor()!=RpgTheme.GOLD,"Unavailable labels differ from selected/active");
        var inventory=SheetSections.raw(snapshot.getAsJsonObject("sheet"),"inventory");for(int i=0;i<5;i++)inventory.addProperty(CurrencyDraft.KEYS.get(i),i*5);check(CharacterSheetUi.currencySummary(inventory).equals("CP 0 · SP 5 · EP 10 · GP 15 · PP 20"),"Equipment currency includes all five units in a compact readable sequence");var panels=list(pane,"panels");check(field(panels.getLast(),"title").equals("Equipment Summary"),"Equipment remains the final bordered panel");for(int[] size:List.of(new int[]{240,135},new int[]{320,180},new int[]{640,360},new int[]{854,480},new int[]{1280,720})){var frame=UiLayout.frame(size[0],size[1],980);var geometry=InventoryWorkspace.geometry(frame);for(var r:geometry)check(r.fits(size[0],size[1])&&r.y()+r.height()<=frame.y()+frame.height()-30,"Both inventory canvas surfaces clear footer at tested logical scales");if(frame.width()-24>=380)check(geometry[0].y()==geometry[1].y()&&geometry[0].height()==geometry[1].height(),"Inventory and Currency share exact outer top/height");var back=CreatorFooter.back(frame);for(int i=0;i<3;i++){var r=CreatorFooter.action(frame,i);check(r.fits(size[0],size[1])&&!r.overlaps(back),"Common footer fits and clears Back");if(i>0)check(!r.overlaps(CreatorFooter.action(frame,i-1)),"Footer group actions remain adjacent and separate");}}
        for(int[] size:List.of(new int[]{240,135},new int[]{320,180},new int[]{640,360})){var frame=UiLayout.frame(size[0],size[1],980);var back=CreatorFooter.back(frame,true);var shell=CharacterShell.layout(frame);check(!back.overlaps(shell.content())&&!back.overlaps(WizardChildLayout.rail(frame)),"Adaptive creator footer clears content and child rail");for(int i=0;i<3;i++){var r=CreatorFooter.action(frame,i,true);check(r.fits(size[0],size[1])&&!r.overlaps(back),"Wrapped creator actions fit small logical viewports");if(i<2)check(!r.overlaps(shell.content()),"Primary actions clear the scrolling workspace");}}
        var reviewShell=CharacterShell.layout(UiLayout.frame(640,360,980));check(CharacterSheetUi.layout(CharacterShell.workspace(reviewShell,true).width()).equipmentTop()<=CharacterShell.workspace(reviewShell,true).height(),"Review uses the summary strip space so its essential core fits the practical viewport");
        var readOnly=new CharacterCanvas(new UiLayout.Rect(0,0,456,300));CharacterSheetUi.build(readOnly,snapshot,true,null,null,null);check(list(readOnly,"markers").size()==6,"Read-only review uses the same centered death markers without widgets");
        var ranger=javax.imageio.ImageIO.read(java.nio.file.Path.of("src/main/resources/assets/tacticalcombat/textures/gui/creator/sprites/ranger.png").toFile());var digest=java.security.MessageDigest.getInstance("SHA-256");for(int y=0;y<ranger.getHeight();y++)for(int x=0;x<ranger.getWidth();x++){int pixel=ranger.getRGB(x,y);digest.update((byte)(pixel>>>16));digest.update((byte)(pixel>>>8));digest.update((byte)pixel);digest.update((byte)(pixel>>>24));}check(java.util.HexFormat.of().formatHex(digest.digest()).equals("714caa08c38256278e0944a2d7ef9e2644a8ee614891f8906a4ab9e4c07c38b6"),"Approved Ranger RGBA and geometry stay unchanged after source cleanup");
        check(CreatorFlow.Step.values().length==9&&DashboardModel.Tab.values().length==6,"Approved destination counts remain unchanged");
        System.out.println("Checkpoint E presentation checks passed: "+count);
    }
}
